INSERT INTO `Objetivo` VALUES (1,'Implementación de un Plan de Mantenimiento','Desarrollar un calendario para actualizaciones regulares de hardware y software, asegurando que los sistemas operen con las versiones más recientes y seguras.',5,'2024-10-22','2025-12-30'),(11,'Mejorar los Tiempos de Elaboración de Propuestas Técnicas','Reducir el tiempo necesario para preparar propuestas técnicas sin comprometer la calidad.',10,'2024-10-22','2025-12-30'),(13,'Mejorar el Manejo de los Tiempos y la Organización de los Temas','Optimizar la gestión del tiempo y la organización de tareas para mejorar la productividad del equipo.',5,'2024-10-22','2025-12-30'),(14,'Uso eficiente de herramientas de registro de proyectos y horas de soporte','Maximizar la efectividad de las herramientas disponibles para el registro y seguimiento de proyectos y horas de soporte, asegurando una correcta contabilización y análisis.',5,'2024-10-22','2025-12-30'),(15,'Mantener Actualizada la Infraestructura de los cliente e Internas','Garantizar que toda la infraestructura tecnológica de los clientes esté al día, funcional y segura, asi como tambien la infraestrucutura AG.',5,'2024-10-22','2025-12-30'),(16,'Seguridad de la información','Proponer e Implementar medidas de seguridad para proteger la información de la empresa y de los clientes.',5,'2024-10-22','2025-12-30'),(17,'Certificaciones Técnicas para el Desarrollo Profesional (Infraestrucutura)','Fomentar el desarrollo técnico a través de certificaciones clave, alineadas con las responsabilidades y necesidades del equipo. ',20,'2024-10-22','2025-12-30'),(18,'Reuniones de Innovación y Mejora Continua','Facilitar reuniones mensuales con el equipo donde se debatan nuevos avances en networking, casos de éxito y lecciones aprendidas de los proyectos recientes. Involucrar a los colaboradores en la creación de propuestas de mejora e incentivos para la participación activa en las soluciones.',5,'2024-10-22','2025-12-30'),(19,'Elaboración de Propuestas de Mejora','Crear un proceso sistemático (reuniones con clientes - interno o externo)para la elaboración de propuestas de optimización tanto interna como para clientes. Cada propuesta debe considerar los beneficios operativos, los costos y las implicancias de seguridad, y ser presentada con un análisis costo-beneficio.',5,'2024-10-22','2025-12-30'),(20,'Elaboración de Informes de Proyectos y Servicios Activos','Elaboración de informes de proyectos / servicios que permitan una visualización más clara del estado de los mismos. Asegurar que los reportes incluyan métricas clave de  desempeño, KPIs y plazos claros, así como la identificación temprana de riesgos.  Elaborar informes de trimestrales del estado de salud de la red interna AG',5,'2024-10-22','2025-12-30'),(21,'Mantenimiento de la Red Interna de AG','Optimizar el mantenimiento de la red interna mediante la adopción de soluciones de monitoreo proactivo que incluyan alertas automatizadas y previsión de fallas. Realizar auditorías trimestrales de la infraestructura para garantizar un rendimiento óptimo.',5,'2024-10-22','2025-12-30'),(22,'Seguridad de la Red AG','Fortalecer la seguridad de la red mediante la implementación de tecnologías avanzadas de prevención de intrusiones (IPS), autenticación multifactor (MFA) y análisis continuo de vulnerabilidades. Establecer políticas de respuesta ante incidentes de seguridad con el equipo para garantizar una resolución rápida.',5,'2024-10-22','2025-12-30'),(23,'Formación y Coaching del Equipo de Networking','Desarrollar un programa formal de mentoría y coaching donde los miembros del equipo reciban formación continua en áreas clave como configuración avanzada de redes, automatización y seguridad. Realizar sesiones mensuales de revisión de desempeño y crecimiento profesional.',10,'2024-10-22','2025-12-30'),(25,'Elaboración de Propuestas Técnicas Adaptadas a las Necesidades del Cliente','Desarrollar la capacidad de elaborar propuestas técnicas precisas y detalladas, alineadas con las necesidades específicas de cada cliente y proyecto, garantizando que las soluciones ofrecidas cumplan con los requisitos técnicos y comerciales. Valorando el Análisis de Requisitos, Desarrollo de Soluciones Técnicas',5,'2024-10-22','2025-12-30'),(26,'Mejorar el Manejo del Tiempo y Organización de Tareas','Adoptar metodologías para organizar las tareas diarias del equipo, priorizando la resolución de incidencias críticas y el avance en proyectos de redes.',5,'2024-10-22','2025-12-30'),(27,'Talleres de Team Building','Realizar actividades trimestrales de team building enfocadas en mejorar la comunicación y la colaboración, integrando ejercicios técnicos que ayuden al equipo a resolver problemas complejos de redes en conjunto.',5,'2024-10-22','2025-12-30'),(28,'Definición de Roles y Responsabilidades','Revisar y ajustar regularmente las responsabilidades de cada colaborador, asegurando que estén alineadas con sus fortalezas y áreas de crecimiento, y que los roles cubran todas las áreas críticas del ciclo de vida de los proyectos de redes.',5,'2024-10-22','2025-12-30'),(29,'Feedback Regular y Constructivo','Implementar sesiones de feedback estructuradas y regulares, tanto individuales como grupales, donde se discutan logros, áreas de mejora y objetivos de desarrollo profesional. Incorporar un sistema de evaluación por competencias para el desarrollo de habilidades técnicas y de liderazgo.',5,'2024-10-22','2025-12-30'),(30,'Sesiones de Capacitación Interdepartamental','Implementar sesiones de feedback estructuradas y regulares, tanto individuales como grupales, donde se discutan logros, áreas de mejora y objetivos de desarrollo profesional. Incorporar un sistema de evaluación por competencias para el desarrollo de habilidades técnicas y de liderazgo.',4,'2024-10-22','2025-12-30'),(31,'Creación de Material de Soporte','Desarrollar un set de materiales actualizados (guías técnicas, infografías, videos) que el equipo comercial pueda utilizar para comprender mejor las soluciones de networking y explicar de manera más efectiva su valor a los clientes.',5,'2024-10-22','2025-12-30'),(32,'Programas de Mentorización','Establecer un programa de mentorización donde los integrantes del equipo de networking guíen a los comerciales sobre las últimas tendencias en tecnología de redes, sus aplicaciones prácticas y cómo estas pueden ser utilizadas para crear propuestas de valor diferenciadas.',10,'2024-10-22','2025-12-30'),(33,'Certificaciones Técnicas para el Desarrollo Profesional (Networking)','Fomentar un plan de certificación técnica que cubra tanto las necesidades actuales de los clientes como las tendencias emergentes, tales como SDN (Software Defined Networking), seguridad en la nube y automatización de redes. Proveer apoyo y recursos para que el equipo obtenga certificaciones relevantes como Cisco CCNA - CCNP, Palo Alto, Huawei  o Fortinet NSE',20,'2024-10-22','2025-12-30'),(34,'Administración de la Seguridad Interna y de Clientes',' Implementar y gestionar plataformas de seguridad compartida para múltiples clientes, garantizando la visibilidad y control sobre la implementación de políticas de seguridad en diferentes entornos. Revisar periódicamente las políticas de cada cliente para asegurar que estén alineadas con sus necesidades y actualizaciones normativas.',10,'2024-10-22','2025-12-30'),(36,'Implementación de Medidas de Control de Acceso en Ambientes','Implementar sistemas de control de acceso basados en roles (RBAC) y autenticación multifactor (MFA) para diferentes clientes, asegurando que cada uno tenga un acceso adaptado a su nivel de seguridad. Realizar auditorías de accesos cada trimestre en cada entorno de cliente para asegurar que los permisos estén correctamente alineados con sus requerimientos.',10,'2024-10-22','2025-12-30'),(39,'Gestión de Actualización de Parches y Vulnerabilidades en Diferentes Entornos','Desarrollar un cronograma de actualización de parches personalizado para cada cliente, automatizando la gestión de parches críticos y vulnerabilidades en función de sus necesidades de operación. Proveer informes mensuales de actualización a cada cliente, asegurando que se mantenga la integridad y seguridad de su infraestructura.',10,'2024-10-22','2025-12-30'),(40,'Respuesta a Incidentes de Seguridad por Cliente','Definir procedimientos específicos para la respuesta a incidentes de seguridad para cada cliente, asegurando que estén alineados con sus SLAs (acuerdos de nivel de servicio). Implementar simulacros de respuesta a incidentes y pruebas de recuperación ante desastres para clientes clave, documentando las mejoras necesarias y generando informes de desempeño.',5,'2024-10-22','2025-12-30'),(42,'Optimización del Manejo de Tiempos y Priorización de Incidencias por Cliente','Utilizar El Service Desk para una mejor visualización y seguimiento de las incidencias Definir tiempos máximos de respuesta y resolución para cada cliente, enfocándose en la mejora continua de la productividad.',5,'2024-10-22','2025-12-30'),(43,'Optimización de Redes y Performance para Múltiples Clientes','Fomentar la Implementación y gestión la segmentación de redes (VLANs) y políticas de QoS (Quality of Service) en los entornos de clientes para garantizar un rendimiento óptimo, independientemente del tamaño o la criticidad de la operación. Realizar evaluaciones trimestrales de rendimiento de red y generar recomendaciones técnicas personalizadas para cada cliente.',10,'2024-10-22','2025-12-30'),(44,'Pruebas de Resiliencia y Alta Disponibilidad por Cliente','Fomentar la implementación de pruebas de alta disponibilidad y recuperación ante fallos en las infraestructuras de clientes, asegurando que los sistemas críticos cuenten con soluciones de redundancia y failover. Proveer informes de resiliencia a cada cliente, resaltando áreas de mejora en sus sistemas y procesos.',10,'2024-10-22','2025-12-30'),(46,'Instalación y Configuración de Equipos','Dominar la instalación y configuración de equipos más complejos (firewalls, switches administrables, servidores), asegurando que estén completamente integrados en el entorno de red de la empresa o del cliente.\nDocumentar cada instalación para generar un repositorio que sirva de referencia futura y para otros miembros del equipo.',10,'2024-10-22','2025-12-30'),(47,'Soporte Técnico de Primer Nivel','		Ampliar el conocimiento en resolución de problemas de segundo nivel, aprendiendo a diagnosticar problemas de red más complejos como la conectividad entre sedes, VPNs, y configuración de firewalls.\nDesarrollar habilidades en la comunicación con usuarios no técnicos para mejorar la eficiencia en la resolución de problemas.',10,'2024-10-22','2025-12-30'),(48,'Monitoreo de la Red LAN','		Identificar y solucionar problemas recurrentes en la red, como latencia, pérdida de paquetes, y conflictos de IP, aprendiendo a implementar soluciones más avanzadas como el balanceo de carga y la optimización de tráfico.\n		Participar en proyectos de mejora continua de la red para optimizar su rendimiento y estabilidad.',5,'2024-10-22','2025-12-30'),(49,'Familiarización con Dispositivos de Red','		Obtener un conocimiento profundo de los dispositivos de red avanzados, como controladores de red inalámbrica, firewalls de próxima generación (NGFW), y sistemas de detección de intrusiones (IDS).\n		Realizar pruebas y simulaciones en entornos controlados para adquirir experiencia en configuraciones complejas.',10,'2024-10-22','2025-12-30'),(50,'Configuración Básica de Switches y Routers','		Aprender configuraciones intermedias y avanzadas en switches y routers, incluyendo protocolos de routing dinámico (OSPF, EIGRP) y tecnologías como STP (Spanning Tree Protocol) y agregación de enlaces.\n		Asegurar la redundancia y la alta disponibilidad en configuraciones críticas.',5,'2024-10-22','2025-12-30'),(51,'Aprender a Usar Herramientas de Monitoreo de Red','		Familiarizarse con herramientas de monitoreo avanzadas como Zabbix, PRTG, o Nagios, aprendiendo a configurar alertas automáticas y generar informes de estado de la red.\n		Usar herramientas de análisis de tráfico como Wireshark para realizar análisis avanzados y diagnósticos detallados de problemas de red.',10,'2024-10-22','2025-12-30'),(52,'Documentación de la Infraestructura de Red','		Mejorar las habilidades de documentación mediante la creación de diagramas detallados con herramientas especializadas como Visio o Lucidchart. Asegurarse de mantener la documentación actualizada tras cada cambio en la infraestructura.\n		Desarrollar una metodología de documentación estándar para que sea clara y comprensible para otros técnicos.',10,'2024-10-22','2025-12-30'),(53,'Gestión de Direcciones IP y Subnetting','		Aprender a diseñar esquemas de direccionamiento IP para redes más grandes y complejas, aplicando técnicas avanzadas de subnetting y VLSM (Variable Length Subnet Masking).\n		Desarrollar un plan de gestión de direcciones IP que contemple el crecimiento futuro y la escalabilidad de la red.',5,'2024-10-22','2025-12-30'),(54,'Resolución Proactiva de Incidencias','		Aprender a anticipar problemas antes de que afecten a los usuarios o al negocio, utilizando herramientas de análisis predictivo o sistemas de monitoreo continuo.\nParticipar en la mejora de los procesos de soporte, proponiendo y ejecutando soluciones para reducir el número de incidencias repetitivas.',5,'2024-10-22','2025-12-30'),(55,'Optimización de Conectividad en Oficinas Remotas','Involucrarse en proyectos que optimicen la conectividad entre múltiples sedes, configurando enlaces redundantes y VPNs seguras para garantizar la conectividad y continuidad del negocio.',5,'2024-10-22','2025-12-30'),(56,'Colaboración en Proyectos de Implementación de Redes','		Participar activamente en proyectos de implementación o actualización de redes de clientes, colaborando con técnicos senior para aprender el ciclo completo de diseño, implementación y mantenimiento de redes complejas.\n		Adquirir experiencia práctica en proyectos que utilicen tecnologías emergentes como redes definidas por software (SDN)',10,'2024-10-22','2025-12-30'),(57,'Mantenimiento del Stock e Inventario:','No solo supervisar y actualizar el inventario de equipos y software, sino también implementar un sistema automatizado de control de inventario utilizando herramientas como Excel avanzado o software especializado (ej. OCS Inventory). Asegurar una revisión bimestral del stock y proponer acciones correctivas para optimizar la disponibilidad de recursos.\nDesarrollar habilidades de análisis para identificar patrones de uso de equipos y proponer mejoras en la gestión del inventario.',10,'2024-10-22','2025-12-30'),(58,'Administración de la Flota de Equipos (Celulares y Notebooks):','Implementar políticas de mantenimiento preventivo y realizar revisiones periódicas de la flota de dispositivos móviles y notebooks, asegurando su correcto funcionamiento. Supervisar los ciclos de vida de los dispositivos y proponer renovaciones o actualizaciones cuando sea necesario.',10,'2024-10-22','2025-12-30'),(59,'Gestión de la Consola de ESET:','No solo monitorear y administrar la consola de ESET, sino también proponer mejoras en las políticas de seguridad. Establecer una rutina de escaneo, revisión de amenazas y aplicar mejores prácticas en la protección de dispositivos. Capacitarse para resolver incidencias de seguridad de nivel N2, como infecciones más complejas o análisis forense básico.\nFamiliarizarse con reportes avanzados de seguridad y colaborar en la implementación de medidas preventivas.\nAdministrar correctamente el licenciamiento del antivirus, eliminando equipos que no formen parte de nuestro parque informático',10,'2024-10-22','2025-12-30'),(60,'Administración del Sistema de Service Desk (SD):','Mejorar la eficiencia en la gestión de tickets al reducir los tiempos de resolución y aumentar la satisfacción del usuario. Adquirir experiencia en la clasificación de incidencias de nivel 2, como problemas de conectividad, administración de usuarios y permisos en Active Directory.\nProponer mejoras en el flujo de trabajo del sistema de tickets para priorizar y asignar incidencias más rápidamente.',10,'2024-10-22','2025-12-30'),(61,'Instalación y Configuración de Equipos:','Además de encargarse de la instalación y configuración de equipos básicos, adquirir habilidades para realizar configuraciones avanzadas en servidores y dispositivos de red. Participar en la creación de procedimientos estandarizados para estas tareas y asegurar que los equipos estén alineados con las políticas de seguridad. Aprender a realizar configuraciones iniciales de infraestructura básica (switches, access points) para reducir dependencias del equipo N2.',10,'2024-10-22','2025-12-30'),(62,'Soporte Técnico de Primer y Segundo Nivel:','No solo proveer asistencia técnica de primer nivel, sino también asumir tareas de segundo nivel en áreas como gestión de usuarios en sistemas de directorio (Active Directory), configuración de VPNs y resolución de problemas de red más complejos. Colaborar con el equipo de N2 para aprender mejores prácticas y reducir la escalación de incidencias. Desarrollar una biblioteca de soluciones comunes para compartir con el equipo, mejorando la tasa de resolución en el primer contacto.',10,'2024-10-22','2025-12-30'),(63,'Control y Reporte de Uso de Equipos:\n','Monitorear el uso de los equipos asignados mediante herramientas avanzadas de monitoreo de rendimiento y generar informes más detallados que incluyan métricas de desempeño y uso del hardware. Proponer recomendaciones específicas para optimizar el uso de recursos y alargar la vida útil de los dispositivos. Aprender a generar reportes automatizados mediante scripts o herramientas de gestión de activos.',10,'2024-10-22','2025-12-30'),(64,'Colaboración en Proyectos de Soporte IT:','Participar activamente en proyectos de soporte IT, asegurando la resolución efectiva de incidencias y la implementación de mejoras técnicas para los clientes, colaborando con diferentes equipos y garantizando la continuidad operativa.',10,'2024-10-22','2025-12-30'),(65,'Dominio del Entorno de Desarrollo Completo','Conocer y dominar el uso de las herramientas y tecnologías estándar de la empresa, incluyendo control de versiones (Git), entornos de desarrollo (IDEs), integración y despliegue continuo (CI/CD), y configuración local para asegurar un entorno de trabajo bien configurado y funcional.\nConfigurar y personalizar el entorno de desarrollo para adaptarlo a proyectos específicos.\nFamiliarizarse con los flujos de trabajo colaborativos que facilitan la revisión de código y la integración de cambios.',10,'2024-10-22','2025-12-30'),(66,'Desarrollo de Funcionalidades Básicas en Proyectos Internos:','Implementar pequeñas funcionalidades en el frontend y backend, respetando las normas de codificación y trabajando en colaboración con el equipo para asegurar que cada desarrollo cumple con los requisitos y estándares de calidad de la empresa.\nContribuir en la programación de módulos de frontend y backend siguiendo los estándares de la empresa.\nParticipar en revisiones de código para aprender mejores prácticas y recibir retroalimentación continua.\nDocumentar cada paso del desarrollo y los retos encontrados, creando un portafolio de aprendizaje y avance.',30,'2024-10-22','2025-12-30'),(67,'Pruebas y Validación de Código para Mejorar la Calidad','Aprender y aplicar buenas prácticas en pruebas unitarias y de integración, contribuyendo al aseguramiento de la calidad del software. Participar en el diseño y ejecución de pruebas funcionales para verificar el correcto funcionamiento de las funcionalidades desarrolladas, adquiriendo experiencia en metodologías de testing automatizado.\nCrear y ejecutar pruebas unitarias para cada módulo de código que desarrolle, garantizando que cada pieza funcione de forma aislada.\nColaborar en el diseño de pruebas de integración y participar en sesiones de prueba para aprender técnicas de testing más avanzadas.',10,'2024-10-22','2025-12-30'),(68,'Entrega de Funcionalidad Completa, Documentación y Presentación al Equipo','Completar de principio a fin una funcionalidad integral que abarque desde la implementación en frontend y backend hasta las pruebas automatizadas y la documentación. Preparar una presentación del código para revisión de equipo y recibir retroalimentación constructiva.\nRealizar una implementación que cubra un flujo de funcionalidad completo, verificando su funcionalidad con pruebas automatizadas.\nDocumentar cada fase del desarrollo y preparar una presentación de la solución para explicar su estructura y lógica al equipo.',10,'2024-10-22','2025-12-30'),(69,'Participación en Mantenimiento y Mejoras de Código Existente','Revisar, analizar y, en su caso, mejorar el código existente en proyectos internos, con el fin de comprender mejores prácticas y optimizar su desempeño. Este objetivo fomenta el crecimiento técnico y ayuda a familiarizarse con proyectos en curso.\nRevisar las funcionalidades existentes, identificar oportunidades de mejora y aplicar buenas prácticas de optimización.\nProponer mejoras o actualizaciones y aprender cómo aplicarlas sin alterar la funcionalidad principal.',10,'2024-10-22','2025-12-30'),(70,'Aprendizaje de Patrones de Diseño y Buenas Prácticas de Programación','Introducirse en los patrones de diseño más comunes (por ejemplo, MVC, Factory, Singleton) para entender cómo estructurar soluciones robustas y escalables, mejorando la calidad del desarrollo a nivel técnico y estructural.\nLeer y aplicar ejemplos de patrones de diseño en las tareas asignadas, usando guías y ejemplos.\nParticipar en discusiones o revisiones de código para ver cómo estos patrones son aplicados por desarrolladores más experimentados.',10,'2024-10-22','2025-12-30'),(71,'Certificaciones Técnicas para el Desarrollo Profesional','Obtener certificaciones de nivel junior como Digital & App Innovation entre otros, y seguir con cursos más avanzados que estén alineados con los desafíos de las app internas.\nEstablecer un plan de desarrollo personal con objetivos anuales de certificación.',30,'2024-10-22','2025-12-30'),(72,'Documentación de Incidencias y Soluciones','Generar documentación detallada de las incidencias recurrentes y las soluciones aplicadas, creando una base de conocimiento accesible para futuros casos similares.',10,'2024-10-22','2025-12-30'),(73,'Gestión de Seguridad de Red y Cumplimiento de Políticas','Realizar revisiones periódicas de la seguridad de la red (firewalls, permisos, configuraciones) asegurando que cumpla con las políticas de seguridad de la empresa y esté actualizada',10,'2024-10-22','2025-12-30'),(74,'Mejora Continua en la Configuración de Equipos de Usuario Final','	Realizar mejoras en la configuración de los dispositivos de usuario final para optimizar su rendimiento y reducir el número de incidencias relacionadas con problemas de configuración.',10,'2024-10-22','2025-12-30'),(75,'Capacitación de Usuarios Finales en Buenas Prácticas','Realizar capacitaciones trimestrales para los usuarios finales sobre buenas prácticas en el uso de equipos y software de la empresa.',10,'2024-10-22','2025-12-30'),(76,'Actualización de Firmware y Software de Infraestructura','	Asegurar que el firmware y software de todos los equipos de infraestructura estén actualizados, previniendo vulnerabilidades y mejorando la estabilidad de la red.',10,'2024-10-22','2025-12-30'),(77,'Monitoreo y Reporte de Rendimiento de la infraestructura','Implementar y mantener un sistema de monitoreo para reportar semanalmente el estado de los recursos de la infraestructura, identificando y resolviendo potenciales problemas de rendimiento.',5,'2024-10-22','2025-12-30'),(78,'Mejora de Procesos de Respuesta a Incidentes','Desarrollar y ajustar procedimientos para la respuesta rápida a incidentes de red y usuarios finales, minimizando los tiempos de diagnóstico y resolución.',5,'2024-10-22','2025-12-30'),(79,'Optimización de Redes Locales y Conectividad',' Llevar a cabo un análisis exhaustivo del rendimiento de la red local y de la infraestructura de conectividad para identificar cuellos de botella, zonas de baja cobertura, y otros problemas que impacten en la calidad de la conexión. Basado en estos hallazgos, desarrollar y presentar un plan de mejora con recomendaciones específicas orientadas a reducir la latencia, optimizar el uso del ancho de banda y mejorar la experiencia general de los usuarios.',5,'2024-10-22','2025-12-30'),(80,'Mantenimiento Proactivo de Infraestructura',' Implementar un plan de mantenimiento proactivo para los equipos de infraestructura críticos (servidores, switches, routers) para prevenir fallas y maximizar el tiempo de actividad.',5,'2024-10-22','2025-12-30'),(81,'Soporte Eficiente a Usuarios Finales','Proporcionar soporte técnico a usuarios finales siguiendo buenas prácticas, manteniendo tiempos de respuesta menores a 15 minutos y resolución del 90% de los casos dentro de las primeras 24 horas.',10,'2024-10-22','2025-12-30'),(82,'Planificación del Proyecto','	Controlar, acompañar y participar en el desarrollo de planes de proyecto exhaustivos que identifiquen todas las fases, tareas, recursos necesarios, presupuestos y entregables.​\n	Utilizar herramientas de gestión de proyectos, incluido el CRM corporativo, para documentar y seguir el progreso del proyecto desde la fase de inicio hasta el cierre.​\n	Colaborar estrechamente con el equipo de preventa para definir el alcance de los nuevos proyectos.​\n	Asegurar que todas las partes interesadas entiendan los requisitos del proyecto y los entregables.​\n	Supervisar y validar las propuestas comerciales para garantizar que incluyan los aspectos necesarios de gestión de proyectos.​\n	Trabajar con el equipo de ventas y preventa para incluir cronogramas realistas y presupuestos detallados.​\nCrear y mantener un calendario de proyecto detallado que coordine las actividades entre diferentes áreas y asegure el uso óptimo de todos los recursos.',20,'2024-10-22','2025-12-30'),(83,'Gestión de Riesgos','Proactivamente identificar potenciales riesgos del proyecto y desarrollar planes de mitigación para abordarlos antes de que afecten al proyecto.​\nRealizar evaluaciones de riesgo regulares durante la vida del proyecto para adaptar las estrategias según sea necesario.​',10,'2024-10-22','2025-12-30'),(84,'Validación y Supervisión','Validar la asignación de recursos humanos y técnicos de manera efectiva, asegurando que los miembros del equipo tengan las competencias necesarias para sus tareas asignadas.​\nSupervisar el desempeño del equipo de proyecto, proporcionando retroalimentación continua y gestionando las dinámicas del equipo para mantener altos niveles de moral y productividad.​\nInterceder siempre que sea posible para velar por la continuidad del equipo de trabajo asignado hasta la finalización del proyecto.',5,'2024-10-22','2025-12-30'),(85,'Gestión de Recursos Técnicos','Asegurar que los recursos técnicos, como hardware y software, herramientas, permisos, seguros, etc., estén adecuadamente provisionados y utilizados eficientemente a lo largo del proyecto.​\nPlanificar y supervisar la agenda del proyecto para garantizar el cumplimiento de los plazos.​\nCoordinar las disponibilidades de todos los miembros del equipo para alinear las entregas con las expectativas del cliente.​\nRevisar regularmente el estado de los proyectos para identificar desviaciones del plan y tomar acciones correctivas',5,'2024-10-22','2025-12-30'),(86,'Reuniones de Seguimiento','Organizar y liderar reuniones regulares con los equipos de proyecto para revisar el progreso, discutir problemas y adaptar los planes de proyecto conforme sea necesario.​\nMantener una comunicación fluida con todos los stakeholders del proyecto, incluidos clientes, proveedores y otros departamentos internos.​\nMantener informado y efectuar las presentaciones de avances hacia la Gerencia de Operaciones.​\nFacilitar la comunicación y colaboración entre diferentes áreas de la empresa.​\nAsegurar que las estrategias y acciones estén alineadas a través de las áreas de operaciones, ventas y administración.​\nSolicitar a los consultores técnicos informes detallados sobre el estado técnico y cualquier desafío operativo que pueda afectar la planificación del proyecto.',10,'2024-10-22','2025-12-30'),(87,'Reportes de Avance','Preparar y presentar informes detallados sobre el estado del/os proyectos a la dirección, gerencia de operaciones y otros stakeholders claves.​\nUtilizar herramientas de visualización de datos para presentar métricas clave de rendimiento de manera clara y efectiva.',10,'2024-10-22','2025-12-30'),(88,'Mantenimiento de Documentación','Desarrollar y mantener una documentación rigurosa para cada proyecto, asegurando que todos los detalles, cambios y decisiones estén bien documentados y sean fácilmente accesibles.​\nAsegurar que la documentación sea precisa y actualizada, reflejando el verdadero estado del proyecto en cualquier momento.​\nMantener una base de datos actualizada de todos los proyectos en curso y futuros en el CRM.​\nDesarrollar y mantener procedimientos actualizados que documenten las prácticas estándares para la gestión de proyectos dentro de la empresa.',10,'2024-10-22','2025-12-30'),(89,'Informes y Análisis','Elaborar análisis post-proyecto para identificar lecciones aprendidas y áreas de mejora.​\nPreparar y distribuir informes periódicos que analicen el progreso general, los desafíos enfrentados y los éxitos del proyecto.​\nPreparar y distribuir minutas detalladas después de cada reunión.',10,'2024-10-22','2025-12-30'),(90,'Visitas a vendors','Deberan realizar 10 visitas a vendors por Q',8,'2024-11-07','2025-12-30'),(91,'Atención a Incidencias y Resolución de Problemas','Lograr una tasa de resolución de incidencias, manteniendo los tiempos de respuesta dentro de los SLA establecidos con el cliente.',5,'2024-11-11','2025-12-30'),(92,' Configuraciones Técnicas y Cambios de Infraestructura','	Realizar configuraciones técnicas a pedido del cliente, cumpliendo con un checklist de calidad y seguridad, documentando todos los cambios de configuración realizados.\nEjecutar configuraciones avanzadas, trabajando bajo la supervisión de un técnico de nivel medio o senior para ampliar conocimientos en infraestructura.\n',10,'2024-12-31','2025-12-30'),(93,'Revisión de Backups y Mantenimiento Preventivo','Realizar revisiones diarias de los backups, detectando cualquier falla en el proceso y tomando acciones correctivas.\nPreparar un reporte semanal para el cliente detallando el estado de los backups y recomendaciones de mejoras en el proceso.',10,'2024-11-11','2025-12-30'),(94,'Gestión de Incidencias con JIRA','Mantener actualizado el sistema de JIRA (del Cliente), documentando cada paso de las incidencias y asegurando que todas las tareas se reflejen con claridad y precisión.\n',5,'2024-11-11','2025-12-30'),(95,'Documentación y Actualización de Procedimientos','	Crear y mantener actualizada una base de conocimientos con procedimientos y soluciones comunes en infraestructura y backups.\nRealizar auditorías mensuales de la documentación para asegurar que esté actualizada y accesible para otros miembros del equipo.\n',10,'2024-11-11','2025-12-30'),(96,'Colaboración y Comunicación','	Participar en reuniones mensuales con el equipo del cliente para comprender mejor sus necesidades y mejorar el soporte.\nMantener comunicación proactiva y transparente con el cliente, informando de cualquier problema crítico de inmediato y asegurando que el cliente esté satisfecho con el servicio.',10,'2024-11-11','2025-12-30'),(97,'Mejora de Eficiencia en Procesos','Identificar áreas de mejora en los procesos de atención a incidencias y revisión de backups, proponiendo al menos una mejora mensualmente.\nAutomatizar tareas repetitivas en la revisión de backups, para reducir el tiempo de trabajo manual y aumentar la eficiencia',10,'2024-11-11','2025-12-30'),(98,'Gestión de Cobranzas','Cumple con el seguimiento de las cobranzas',10,'2024-11-19','2025-12-31');
